```
class Password {
  constructor(length) {
    this.length = length;
    this.chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-={}:?><~';
  }

  generate() {
    let password = '';
    for (let i = 0; i < this.length; i++) {
      password += this.chars.charAt(Math.floor(Math.random() * this.chars.length));
    }
    return password;
  }

  generateWithNumberAndSymbols() {
    let password = '';
    let numbers = '0123456789';
    let symbols = '!@#$%^&*()_+-={}:?><~';
    let chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';

    for (let i = 0; i < this.length; i++) {
      let randomType = Math.floor(Math.random() * 3);
      switch (randomType) {
        case 0:
          password += numbers.charAt(Math.floor(Math.random() * numbers.length));
          break;
        case 1:
          password += symbols.charAt(Math.floor(Math.random() * symbols.length));
          break;
        default:
          password += chars.charAt(Math.floor(Math.random() * chars.length));
      }
    }
    return password;
  }
}
```
