        DatagramSocket socket = new DatagramSocket(4321);

        // Loop infinito para capturar pacotes
        while (true) {
            // Recebe um pacote
            DatagramPacket packet = new DatagramPacket(new byte[1024], 1024);
            socket.receive(packet);

            // Imprime as informações do pacote capturado
            System.out.println("IP FONT: " + packet.getAddress());
            System.out.println("PORT FONT: " + packet.getPort());
            System.out.println("DATA: " + new String(packet.getData(), 0, packet.getLength()));
            System.out.println();
        }
    }
}
```
