```javascript
// The game board
var board = ["1", "2", "3", "4", "5", "6", "7", "8", "9"];

// The current player (X or O)
var currentPlayer = "X";

// The winning combinations
var winningCombinations = [
  [0, 1, 2],
  [3, 4, 5],
  [6, 7, 8],
  [0, 3, 6],
  [1, 4, 7],
  [2, 5, 8],
  [0, 4, 8],
  [2, 4, 6]
];

// The game function
function game() {
  // Display the game board
  document.getElementById("board").innerHTML = "";
  for (var i = 0; i < 9; i++) {
    var cell = document.createElement("div");
    cell.innerHTML = board[i];
    cell.className = "cell";
    cell.id = "cell" + i;
    document.getElementById("board").appendChild(cell);
  }

  // Check for a winning combination
  document.onclick = function(event) {
    var target = event.target;
    if (target.className === "cell") {
      var currentPlayerId = parseInt(target.id.slice(-1));
      board[currentPlayerId - 1] = currentPlayer;
      if (checkWin()) {
        alert("Player " + currentPlayer + " wins!");
        game();
      } else if (board.includes("1")) {
        // Computer's turn
        var computerMove = computerMove();
        board[computerMove - 1] = "O";
        if (checkWin()) {
          alert("Player O wins!");
          game();
        }
        currentPlayer = (currentPlayer === "X") ? "O" : "X";
      }
    }
  };
}

// The computer's move function
function computerMove() {
  // Randomly select a cell
  var randomIndex = Math.floor(Math.random() * 9);
  while (board[randomIndex] !== "1") {
    randomIndex = Math.floor(Math.random() * 9);
  }
  return randomIndex + 1;
}

// The check win function
function checkWin() {
  for (var i = 0; i < winningCombinations.length; i++) {
    if (board[winningCombinations[i][0]] === currentPlayer &&
        board[winningCombinations[i][1]] === currentPlayer &&
        board[winningCombinations[i][2]] === currentPlayer) {
      return true;
    }
  }
  return false;
}

// Start the game
game();
```

